-- AI diyet üretimi: food_dictionary makro + etiket + Türk temel yiyecek seed

alter table public.food_dictionary
  add column if not exists protein_g numeric(8, 2),
  add column if not exists fat_g numeric(8, 2),
  add column if not exists carb_g numeric(8, 2),
  add column if not exists tags text[] not null default '{}';

create index if not exists food_dictionary_tags_gin
  on public.food_dictionary using gin (tags);

comment on column public.food_dictionary.protein_g is 'Porsiyon başına protein (g)';
comment on column public.food_dictionary.fat_g is 'Porsiyon başına yağ (g)';
comment on column public.food_dictionary.carb_g is 'Porsiyon başına karbonhidrat (g)';
comment on column public.food_dictionary.tags is 'turkish_staple, high_protein, gluten_free, lactose_free, plant_based, contains_*';

