on conflict (name_normalized) do update set
  cal_per_unit = excluded.cal_per_unit,
  unit = excluded.unit,
  protein_g = excluded.protein_g,
  fat_g = excluded.fat_g,
  carb_g = excluded.carb_g,
  tags = excluded.tags,
  source = case
    when public.food_dictionary.source = 'manual' then 'manual'
    else excluded.source
  end,
  updated_at = now();
